<!DOCTYPE html> <html lang="{{ str_replace('_', '-', app()->getLocale()) }}" x-data="{ mobileMenu: false, ...theme }" x-init="init()" :class="{ 'dark': dark }"> <head> <meta charset="utf-8"> <meta name="viewport" content="width=device-width, initial-scale=1"> <meta name="csrf-token" content="{{ csrf_token() }}"> <title>Design Preview - Present</title> <!-- Fonts --> <link rel="preconnect" href="https://fonts.bunny.net"> <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600;700;800&family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" /> <!-- Styles / Scripts --> @vite() </head> <body> <div class="min-vh-100 bg-light bg-dark-bg"> @include('layouts.navigation') <!-- Page Heading --> <header class="bg-white bg-dark-card border-bottom border-dark"> <div class="container py-4"> <h1 class="fs-2 fw-bold text-white">Design Preview</h1> <p class="mt-2 text-muted">A showcase of UI components matching the Figma prototype style.</p> </div> </header> <!-- Page Content --> <main> <section class="py-5"> <div class="container"> <div class="row gap-4 row-cols-md-2 row-cols-lg-3"> <!-- Button Variants --> <div class="card p-4"> <h2 class="fs-4 fw-semibold mb-4 text-white">Buttons</h2> <div class="gap-3"> <x-primary-button>Primary</x-primary-button> <x-secondary-button>Secondary (Outline)</x-secondary-button> <x-danger-button>Danger</x-danger-button> <button class="btn btn btn-outline-secondary">Ghost</button> <button class="btn btn-dark">Black</button> </div> </div> <!-- Inputs --> <div class="card p-4"> <h2 class="fs-4 fw-semibold mb-4 text-white">Form Elements</h2> <div class="gap-4"> <x-input-label for="email" value="Email Address" /> <x-text-input id="email" type="email" placeholder="you@example.com" /> <x-input-label for="password" value="Password" /> <x-text-input id="password" type="password" placeholder="••••••••" /> <div class="d-flex align-items-center gap-3"> <x-checkbox id="remember" name="remember" checked>false</x-checkbox> <span class="fs-6 text-muted">Remember me</span> </div> <x-input-label :messages="" /> </div> </div> <!-- Cards --> <div class="col-md-8 card p-4"> <h2 class="fs-4 fw-semibold mb-4 text-white">Card Variants</h2> <div class="row gap-3 row-cols-3"> <div class="card p-4"> <h3 class="fw-semibold text-white">Default Card</h3> <p class="mt-2 fs-6 text-muted">Standard card with padding.</p> </div> <div class="card-border p-4"> <h3 class="fw-semibold text-white">Card Border</h3> <p class="mt-2 fs-6 text-muted">Card with border only.</p> </div> <div class=" p-4"> <h3 class="fw-semibold text-white">Hover Card</h3> <p class="mt-2 fs-6 text-muted">Lifts on hover.</p> </div> <div class="stat-card p-4 text-center"> <p class="fs-3 fw-bold text-white">124</p> <p class="fs-6 text-muted">Active Users</p> </div> <div class="stat-card-border p-4 text-center"> <p class="fs-3 fw-bold text-white">98%</p> <p class="fs-6 text-muted">Uptime</p> </div> <div class="card p-4 dotted-row"> <h3 class="fw-semibold text-white">Dotted Grid</h3> <p class="mt-2 fs-6 text-muted">Background with dot pattern.</p> </div> </div> </div> <!-- Nav Links --> <div class="card p-4"> <h2 class="fs-4 fw-semibold mb-4 text-white">Navigation Links</h2> <div class="gap-2"> <x-nav-link :active="true">Dashboard</x-nav-link> <x-nav-link :active="false">Students</x-nav-link> <x-nav-link :active="false">Attendance</x-nav-link> <x-nav-link :active="false">Reports</x-nav-link> </div> </div> <!-- Badges --> <div class="card p-4"> <h2 class="fs-4 fw-semibold mb-4 text-white">Badges</h2> <div class="d-flex-wrap gap-2"> <span class="badge bg-primary">Blue</span> <span class="badge bg-success">Green</span> <span class="badge bg-warning">Yellow</span> <span class="badge bg-danger">Red</span> <span class="badge badge-gray">Gray</span> </div> </div> <!-- Modal Trigger --> <div class="card p-4"> <h2 class="fs-4 fw-semibold mb-4 text-white">Modal</h2> <button @click="showModal = true" class="btn btn-primary"> Open Modal </button> <x-modal name="design-modal" :show="showModal" @click.outside="showModal = false"> <div class="gap-4"> <h3 class="fs-4 fw-bold text-white">Modal Title</h3> <p class="text-muted">This is a sample modal using the updated card-border style.</p> <div class="d-flex justify-content-end gap-3"> <x-secondary-button @click="showModal = false">Close</x-secondary-button> <x-primary-button @click="showModal = false">Save Changes</x-primary-button> </div> </div> </x-modal> </div> </div> </div> </section> </main> </div> <script> // Alpine data for modal control document.addEventListener('alpine:init', () => { Alpine.data('designPreview', () => ({ showModal: false })) }) </script> </body> </html>